sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 keyColor;
uniform float similarity;
uniform float softness;
uniform float spill;
uniform float lumaProtect;
uniform float chokePx;
uniform float featherPx;
uniform float showMatte;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float chromaA(float2 p) {
    float3 s = unp(tex(p));
    float3 key = float3(keyColor.rgb);
    float2 kc = float2(dot(key, float3(-0.168736, -0.331264, 0.5)), dot(key, float3(0.5, -0.418688, -0.081312)));
    float2 pc = float2(dot(s, float3(-0.168736, -0.331264, 0.5)), dot(s, float3(0.5, -0.418688, -0.081312)));
    float d = distance(kc, pc);
    float a = smoothstep(similarity * 0.5, similarity * 0.5 + softness + 0.001, d);
    return mix(a, 1.0, lumaProtect * smoothstep(0.7, 1.0, luma(s)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float a = chromaA(coord);
    if (chokePx > 0.01) {
        float m1 = min(chromaA(coord + float2(chokePx, 0.0)), chromaA(coord - float2(chokePx, 0.0)));
        float m2 = min(chromaA(coord + float2(0.0, chokePx)), chromaA(coord - float2(0.0, chokePx)));
        a = min(a, min(m1, m2));
    }
    if (featherPx > 0.01) {
        a = (a * 2.0 + chromaA(coord + float2(featherPx, 0.0)) + chromaA(coord - float2(featherPx, 0.0)) + chromaA(coord + float2(0.0, featherPx)) + chromaA(coord - float2(0.0, featherPx))) / 6.0;
    }
    float3 kn = normalize(float3(keyColor.rgb) + 0.0001);
    float3 o = s - kn * saturate(dot(s - float3(luma(s)), kn)) * spill;
    float4 r = float4(saturate(o) * c.a * a, c.a * a);
    if (showMatte > 0.5) r = float4(float3(a) * c.a, c.a);
    return fin(c, r, opacity);
}
